<script setup lang="ts">import {useMatches} from '../stores/store';import {fmtTime} from '../data/mock';const ms:any=useMatches();function printPage(){window.print()}</script><template><h2>Print Fixtures / Ratiba ya Kuchapisha</h2><button @click="printPage">Print / Chapisha</button><table class="fixtures"><tr><th>Time (EAT)</th><th>League • Country</th><th>Match</th><th>1</th><th>X</th><th>2</th></tr><tr v-for="m in ms.list" :key="m.id"><td>{{fmtTime(m.kickoff)}}</td><td>{{m.league}} • {{m.country}}</td><td>{{m.home}} vs {{m.away}}</td><td v-for="o in m.odds" :key="o.sel">{{o.price.toFixed(2)}}</td></tr></table></template>